export function toTsModule(sections, faq = []) {
  const body = sections.map((s) => ({
    id: s.id,
    h1: s.h1,
    h2: s.h2,
    h3: s.h3,
    p: s.p,
    links: s.links,
    buttons: s.buttons,
    imgs: s.imgs.map(({ alt, ratio }) => ({ alt, ratio })),
  }));
  return (
    '// Generated by tools/copy-to-ts.mjs from reference/<slug>/copy.json and faq.json.\n' +
    `export const sections = ${JSON.stringify(body, null, 2)} as const;\n\n` +
    `export const faq = ${JSON.stringify(faq, null, 2)} as const;\n`
  );
}
